#!/usr/bin/env bash
set -Eeuo pipefail

# Historical A/B rollback:
#   exact VISGRID V20 sensor + existing 1321-shard GLOBAL topology
#
# This intentionally DOES NOT modify:
#   - OpenMW binary
#   - topology.lua / topology_cells
#   - doorgraph.lua / doorgraph_cells
#   - navmesh.db
#
# It DOES:
#   - back up the current live visgrid.lua and launcher
#   - install the exact historical V20 sensor
#   - disable only the launcher's V23 auto-profile copy block so V23 cannot
#     overwrite V20 on startup
#
# Usage:
#   ./test_visgrid_historical_v20_global.sh apply
#   ./test_visgrid_historical_v20_global.sh status
#   ./test_visgrid_historical_v20_global.sh rollback

DEV="${TSP_DEV:-root@192.168.1.25}"
ACTION="${1:-status}"

ROOT="/mnt/SDCARD/data/ports/openmw51"
BASE="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid"
LIVE="$BASE/visgrid.lua"
TOPO="$BASE/topology.lua"
TOPO_CELLS="$BASE/topology_cells"
DOOR="$BASE/doorgraph.lua"
DOOR_CELLS="$BASE/doorgraph_cells"
GAME="$ROOT/bin/openmw-0.51"
DB="/mnt/UDISK/openmw51-nav/navmesh.db"

EXPECTED_V20_SHA="2ef92caeb5f8cdc8c95251aaa7fbe6332939a7cce6f242b752f6901c16becd9b"
EXPECTED_GAME_SHA="5ba39a9869c592f1e21349521ad19fce0a04c6d03bb378c22170929c9792c555"
EXPECTED_TOPO_COUNT="1321"

SSH=(ssh -o BatchMode=yes -o ConnectTimeout=8)
SCP=(scp -q -o BatchMode=yes -o ConnectTimeout=8)

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

resolve_launcher() {
    "${SSH[@]}" "$DEV" '
        for p in \
          /mnt/sdcard/mmcblk1p1/Roms/PORTS/Morrowind_51.sh \
          /mnt/SDCARD/Roms/PORTS/Morrowind_51.sh \
          /mnt/SDCARD/Emus/PORTS/../../Roms/PORTS/Morrowind_51.sh
        do
            if [ -f "$p" ]; then
                readlink -f "$p" 2>/dev/null || printf "%s\n" "$p"
                exit 0
            fi
        done
        exit 1
    '
}

ensure_game_closed() {
    if "${SSH[@]}" "$DEV" \
        'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
    then
        echo "ERROR: OpenMW is running. Exit the game normally first."
        exit 20
    fi
}

write_v20_payload() {
    base64 -d > "$TMP/visgrid-v20.lua" <<'__V20_PAYLOAD__'

__V20_PAYLOAD__

    got="$(sha256sum "$TMP/visgrid-v20.lua" | awk '{print $1}')"
    if [ "$got" != "$EXPECTED_V20_SHA" ]; then
        echo "ERROR: embedded V20 payload hash mismatch."
        echo "Expected: $EXPECTED_V20_SHA"
        echo "Got:      $got"
        exit 30
    fi
}

show_state() {
    LAUNCHER="$(resolve_launcher)" || {
        echo "ERROR: Morrowind_51.sh not found."
        exit 21
    }

    echo "=================================================================="
    echo "VISGRID HISTORICAL V20 + GLOBAL TOPOLOGY STATUS"
    echo "=================================================================="
    echo "Launcher: $LAUNCHER"
    echo

    "${SSH[@]}" "$DEV" "
        set -e
        echo '===== GAME / SENSOR / TOPOLOGY ====='
        sha256sum '$GAME' '$LIVE' '$TOPO' 2>/dev/null || true
        echo
        printf 'topology_shards='
        find '$TOPO_CELLS' -maxdepth 1 -type f -name '*.lua' 2>/dev/null | wc -l
        printf 'doorgraph_shards='
        if [ -d '$DOOR_CELLS' ]; then
            find '$DOOR_CELLS' -maxdepth 1 -type f -name '*.lua' 2>/dev/null | wc -l
        else
            echo 0
        fi
        echo
        echo '===== SENSOR MARKERS ====='
        grep -nE \
          'TSP_VISGRID_LUA_V20_THRESHOLD_LATCH|TSP_VISGRID_LUA_V21|TSP_VISGRID_LUA_V22|TSP_VISGRID_LUA_V23' \
          '$LIVE' 2>/dev/null | head -30 || true
        echo
        echo '===== GLOBAL TOPOLOGY MARKER ====='
        grep -n -m1 'TSP_VISGRID_GLOBAL_TOPOLOGY_V1' '$TOPO' 2>/dev/null || true
        echo
        echo '===== LAUNCHER SENSOR CONTROL ====='
        grep -nE \
          'TSP_VISGRID_HISTORICAL_V20_GLOBAL|TSP_VISGRID_V23_PROFILE|v23_profiles|TSP_VISGRID_SELECTED' \
          '$LAUNCHER' 2>/dev/null | head -60 || true
        echo
        echo '===== CANONICAL NAVMESH DB ====='
        stat -c '%s %Y %n' '$DB' 2>/dev/null || true
    "
}

apply_v20() {
    ensure_game_closed

    LAUNCHER="$(resolve_launcher)" || {
        echo "ERROR: Morrowind_51.sh not found."
        exit 21
    }

    write_v20_payload

    echo "=================================================================="
    echo "HISTORICAL A/B: EXACT V20 + EXISTING GLOBAL TOPOLOGY"
    echo "=================================================================="
    echo "Device:   $DEV"
    echo "Launcher: $LAUNCHER"
    echo

    GAME_SHA="$("${SSH[@]}" "$DEV" "sha256sum '$GAME'" | awk '{print $1}')"
    TOPO_COUNT="$("${SSH[@]}" "$DEV" \
        "find '$TOPO_CELLS' -maxdepth 1 -type f -name '*.lua' | wc -l" |
        awk '{print $1}')"

    echo "game SHA:         $GAME_SHA"
    echo "topology shards:  $TOPO_COUNT"

    if [ "$GAME_SHA" != "$EXPECTED_GAME_SHA" ]; then
        echo
        echo "ERROR: game binary is not the binary used by the first global-topology state."
        echo "Expected: $EXPECTED_GAME_SHA"
        echo "Got:      $GAME_SHA"
        echo "Nothing changed."
        exit 31
    fi

    if [ "$TOPO_COUNT" != "$EXPECTED_TOPO_COUNT" ]; then
        echo
        echo "ERROR: expected exactly 1321 global topology shards."
        echo "Got: $TOPO_COUNT"
        echo "Nothing changed."
        exit 32
    fi

    if ! "${SSH[@]}" "$DEV" \
        "grep -Fq 'TSP_VISGRID_GLOBAL_TOPOLOGY_V1' '$TOPO'"
    then
        echo "ERROR: global topology marker missing. Nothing changed."
        exit 33
    fi

    "${SCP[@]}" "$DEV:$LAUNCHER" "$TMP/launcher.current"

    python3 - "$TMP/launcher.current" "$TMP/launcher.v20" <<'PY_PATCH_LAUNCHER'
from pathlib import Path
import sys

src = Path(sys.argv[1]).read_text(
    encoding="utf-8", errors="surrogateescape"
)

begin = "# >>> TSP_VISGRID_V23_PROFILE BEGIN"
end   = "# <<< TSP_VISGRID_V23_PROFILE END"

replacement = '''# >>> TSP_VISGRID_HISTORICAL_V20_GLOBAL BEGIN
# Historical A/B test: exact V20 sensor is installed by the host controller.
# IMPORTANT: do not auto-copy a V23 profile over visgrid.lua on startup.
TSP_VISGRID_DIR="$GAMEDIR/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid"
TSP_VISGRID_LIVE="$TSP_VISGRID_DIR/visgrid.lua"
TSP_VISGRID_LIVE_SHA="$(
    sha256sum "$TSP_VISGRID_LIVE" 2>/dev/null | awk 'NF {print $1; exit}'
)"
echo "Visgrid Historical=V20-global"
echo "Visgrid Profile=exact-v20-with-1321-global-topology"
echo "Visgrid SHA=$TSP_VISGRID_LIVE_SHA"
# <<< TSP_VISGRID_HISTORICAL_V20_GLOBAL END'''

if begin in src or end in src:
    if src.count(begin) != 1 or src.count(end) != 1:
        raise SystemExit(
            "ERROR: V23 launcher markers are not unique; refusing to guess."
        )
    a = src.index(begin)
    b = src.index(end, a) + len(end)
    out = src[:a] + replacement + src[b:]
else:
    hbegin = "# >>> TSP_VISGRID_HISTORICAL_V20_GLOBAL BEGIN"
    hend   = "# <<< TSP_VISGRID_HISTORICAL_V20_GLOBAL END"
    if hbegin in src and hend in src:
        out = src
    else:
        danger = ("v23_profiles", "TSP_VISGRID_SELECTED", "visgrid-v23-t")
        if any(x in src for x in danger):
            raise SystemExit(
                "ERROR: launcher contains V23 profile-selection code but the "
                "known block markers are absent. Refusing to patch ambiguously."
            )
        out = src + "\n\n" + replacement + "\n"

Path(sys.argv[2]).write_text(
    out, encoding="utf-8", errors="surrogateescape", newline="\n"
)
PY_PATCH_LAUNCHER

    chmod +x "$TMP/launcher.v20"
    bash -n "$TMP/launcher.v20"

    if grep -qE '^[[:space:]]*TSP_VISGRID_SELECTED=' "$TMP/launcher.v20"; then
        echo "ERROR: active TSP_VISGRID_SELECTED assignment survived launcher patch."
        exit 34
    fi

    STAMP="$(date +%Y%m%d-%H%M%S)"
    BACK="$ROOT/backups/visgrid-historical-v20-global-$STAMP"
    POINTER="$ROOT/backups/visgrid-historical-v20-global.latest"

    "${SCP[@]}" "$TMP/visgrid-v20.lua" "$DEV:/tmp/tsp-visgrid-v20-global.lua"
    "${SCP[@]}" "$TMP/launcher.v20" "$DEV:/tmp/Morrowind_51.v20-global.sh"

    "${SSH[@]}" "$DEV" "
        set -Eeuo pipefail

        mkdir -p '$BACK'

        cp -p '$LIVE' '$BACK/visgrid.lua.before-v20-global'
        cp -p '$LAUNCHER' '$BACK/Morrowind_51.sh.before-v20-global'

        {
            echo 'Historical target: exact V20 sensor + existing global topology'
            echo \"Date: \$(date)\"
            echo
            echo '===== BEFORE HASHES ====='
            sha256sum '$GAME' '$LIVE' '$TOPO' '$LAUNCHER' 2>/dev/null || true
            echo
            echo '===== COUNTS ====='
            printf 'topology_shards='
            find '$TOPO_CELLS' -maxdepth 1 -type f -name '*.lua' | wc -l
            printf 'doorgraph_shards='
            if [ -d '$DOOR_CELLS' ]; then
                find '$DOOR_CELLS' -maxdepth 1 -type f -name '*.lua' | wc -l
            else
                echo 0
            fi
            echo
            echo '===== NAVMESH DB ====='
            stat -c '%s %Y %n' '$DB' 2>/dev/null || true
        } > '$BACK/STATE-BEFORE.txt'

        printf '%s\n' '$LAUNCHER' > '$BACK/launcher.path'

        test \"\$(sha256sum /tmp/tsp-visgrid-v20-global.lua | awk '{print \$1}')\" = '$EXPECTED_V20_SHA'

        cp -f /tmp/tsp-visgrid-v20-global.lua '$LIVE.v20-new'
        chmod 644 '$LIVE.v20-new'
        mv -f '$LIVE.v20-new' '$LIVE'

        cp -f /tmp/Morrowind_51.v20-global.sh '$LAUNCHER.v20-new'
        chmod +x '$LAUNCHER.v20-new'
        mv -f '$LAUNCHER.v20-new' '$LAUNCHER'

        rm -f /tmp/tsp-visgrid-v20-global.lua /tmp/Morrowind_51.v20-global.sh
        sync

        test \"\$(sha256sum '$LIVE' | awk '{print \$1}')\" = '$EXPECTED_V20_SHA'
        grep -Fq 'TSP_VISGRID_LUA_V20_THRESHOLD_LATCH' '$LIVE'
        ! grep -Fq 'TSP_VISGRID_LUA_V21_DOORGRAPH_VIEWHOLD' '$LIVE'
        grep -Fq 'TSP_VISGRID_HISTORICAL_V20_GLOBAL' '$LAUNCHER'
        ! grep -q '^[[:space:]]*TSP_VISGRID_SELECTED=' '$LAUNCHER'

        printf '%s\n' '$BACK' > '$POINTER'

        {
            echo
            echo '===== AFTER HASHES ====='
            sha256sum '$GAME' '$LIVE' '$TOPO' '$LAUNCHER' 2>/dev/null || true
        } >> '$BACK/STATE-BEFORE.txt'
    "

    echo
    echo "===== VERIFY HISTORICAL TARGET ====="
    LIVE_SHA="$("${SSH[@]}" "$DEV" "sha256sum '$LIVE'" | awk '{print $1}')"
    GAME_SHA_AFTER="$("${SSH[@]}" "$DEV" "sha256sum '$GAME'" | awk '{print $1}')"
    TOPO_COUNT_AFTER="$("${SSH[@]}" "$DEV" \
        "find '$TOPO_CELLS' -maxdepth 1 -type f -name '*.lua' | wc -l" |
        awk '{print $1}')"

    echo "V20 sensor SHA:    $LIVE_SHA"
    echo "game SHA:          $GAME_SHA_AFTER"
    echo "topology shards:   $TOPO_COUNT_AFTER"
    echo "backup:             $BACK"

    test "$LIVE_SHA" = "$EXPECTED_V20_SHA"
    test "$GAME_SHA_AFTER" = "$EXPECTED_GAME_SHA"
    test "$TOPO_COUNT_AFTER" = "$EXPECTED_TOPO_COUNT"

    echo
    echo "PASS: historical V20 + global topology state is active."
    echo
    echo "The real-door sidecar may still exist on disk, but V20 has no V21"
    echo "doorgraph loader and therefore does not use it."
    echo
    echo "Run:"
    echo "  $0 status"
    echo
    echo "Rollback:"
    echo "  $0 rollback"
}

rollback_v20() {
    ensure_game_closed

    POINTER="$ROOT/backups/visgrid-historical-v20-global.latest"

    BACK="$("${SSH[@]}" "$DEV" "
        set -e
        test -s '$POINTER'
        cat '$POINTER'
    ")" || {
        echo "ERROR: no historical-V20 rollback pointer found on device."
        exit 40
    }

    echo "Restoring from:"
    echo "  $BACK"

    "${SSH[@]}" "$DEV" "
        set -Eeuo pipefail
        test -s '$BACK/visgrid.lua.before-v20-global'
        test -s '$BACK/Morrowind_51.sh.before-v20-global'
        test -s '$BACK/launcher.path'

        LAUNCHER=\$(cat '$BACK/launcher.path')
        test -n \"\$LAUNCHER\"

        cp -p '$BACK/visgrid.lua.before-v20-global' '$LIVE.restore-new'
        mv -f '$LIVE.restore-new' '$LIVE'

        cp -p '$BACK/Morrowind_51.sh.before-v20-global' \"\$LAUNCHER.restore-new\"
        chmod +x \"\$LAUNCHER.restore-new\"
        mv -f \"\$LAUNCHER.restore-new\" \"\$LAUNCHER\"

        sync

        echo
        echo '===== RESTORED HASHES ====='
        sha256sum '$LIVE' \"\$LAUNCHER\" 2>/dev/null || true
    "

    echo
    echo "PASS: pre-test VISGRID sensor and launcher restored."
}

case "$ACTION" in
    apply)
        apply_v20
        ;;
    status)
        show_state
        ;;
    rollback)
        rollback_v20
        ;;
    *)
        echo "Usage:"
        echo "  $0 apply"
        echo "  $0 status"
        echo "  $0 rollback"
        exit 2
        ;;
esac
